<?php

namespace hcFormHandling;

function xssPrevention($var){

    return (string) $varSanitized = \htmlspecialchars($var, ENT_QUOTES, 'UTF-8');

}

/**
 * Render errors generated by forms
 */
function renderErrors($errors) {

    $output = [];

    if (!empty($errors)) {

        $output[] = '<ul class="errors">';

        foreach ($errors as $error) {
            $output[] = '   <li>' . $error . '</li>';
        }

        $output[] = '</ul>';

    }

    return implode(PHP_EOL, $output);

}

?>